arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap');

:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2128;
  --bg-code: #0d1117;
  --border: #30363d;
  --border-light: #21262d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent-green: #00e5a0;
  --accent-green-dim: rgba(0,229,160,0.12);
  --accent-blue: #475F91;
  --accent-blue-light: #5878b5;
  --accent-cyan: #39d2e6;
  --accent-purple: #b87fff;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

code, pre, .font-mono {
  font-family: 'JetBrains Mono', 'Fira Code', monospace;
}

/* Scrollbar */
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: var(--bg-primary); }
::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }
::-webkit-scrollbar-thumb:hover { background: var(--text-muted); }

/* Navigation */
.nav {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(13,17,23,0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-light);
}

.nav-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
  height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav-brand {
  font-weight: 700;
  font-size: 1.125rem;
  color: var(--text-primary);
  text-decoration: none;
  display: flex;
  align-items: center;
  gap: 10px;
}

.nav-brand svg { flex-shrink: 0; }

.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
  list-style: none;
}

.nav-links a {
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 0.875rem;
  font-weight: 500;
  transition: color 0.15s;
}

.nav-links a:hover { color: var(--text-primary); }

.nav-right {
  display: flex;
  align-items: center;
  gap: 16px;
}

.nav-search {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 14px;
  border: 1px solid var(--border);
  border-radius: 8px;
  color: var(--text-muted);
  font-size: 0.8125rem;
  cursor: pointer;
  background: var(--bg-secondary);
  transition: border-color 0.15s;
}

.nav-search:hover { border-color: var(--text-muted); }

.nav-search kbd {
  background: var(--bg-tertiary);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 6px;
  font-size: 0.6875rem;
  font-family: 'Inter', sans-serif;
}

.nav-login {
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 0.875rem;
  font-weight: 500;
  transition: color 0.15s;
}

.nav-login:hover { color: var(--text-primary); }

/* Mobile nav toggle */
.nav-toggle {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 4px;
}

.mobile-menu {
  display: none;
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-light);
  padding: 16px 24px;
}

.mobile-menu.open { display: block; }

.mobile-menu a {
  display: block;
  color: var(--text-secondary);
  text-decoration: none;
  padding: 10px 0;
  font-size: 0.9375rem;
  font-weight: 500;
}

.mobile-menu a:hover { color: var(--text-primary); }

@media (max-width: 768px) {
  .nav-links, .nav-right { display: none; }
  .nav-toggle { display: block; }
}

/* Container */
.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.container-narrow {
  max-width: 960px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Hero */
.hero {
  padding: 80px 0 64px;
  text-align: center;
}

.hero h1 {
  font-size: clamp(2rem, 5vw, 3.25rem);
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.03em;
  margin-bottom: 20px;
}

.hero p {
  font-size: 1.125rem;
  color: var(--text-secondary);
  max-width: 640px;
  margin: 0 auto 32px;
  line-height: 1.7;
}

.hero-ctas {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 20px;
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.15s;
  cursor: pointer;
  border: none;
  font-family: inherit;
}

.btn-primary {
  background: var(--accent-green);
  color: #0d1117;
}

.btn-primary:hover { background: #33edb6; box-shadow: 0 0 20px rgba(0,229,160,0.25); }

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1px solid var(--border);
}

.btn-secondary:hover { border-color: var(--text-muted); background: var(--bg-secondary); }

.btn-ghost {
  background: transparent;
  color: var(--accent-green);
  padding: 10px 12px;
}

.btn-ghost:hover { background: var(--accent-green-dim); }

.btn-arrow::after { content: '→'; }

/* Section */
.section {
  padding: 64px 0;
}

.section-title {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.section-subtitle {
  color: var(--text-secondary);
  font-size: 1rem;
  max-width: 560px;
  line-height: 1.7;
  margin-bottom: 40px;
}

/* Cards */
.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

@media (max-width: 768px) { .card-grid { grid-template-columns: 1fr; } }
@media (min-width: 769px) and (max-width: 1024px) { .card-grid { grid-template-columns: repeat(2, 1fr); } }

.card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: 12px;
  padding: 28px;
  transition: all 0.2s;
}

.card:hover {
  border-color: var(--border);
  box-shadow: 0 4px 24px rgba(0,0,0,0.3);
  transform: translateY(-2px);
}

.card-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  font-size: 1.25rem;
}

.card-icon.green { background: var(--accent-green-dim); color: var(--accent-green); }
.card-icon.blue { background: rgba(71,95,145,0.2); color: var(--accent-blue-light); }
.card-icon.cyan { background: rgba(57,210,230,0.12); color: var(--accent-cyan); }
.card-icon.purple { background: rgba(184,127,255,0.12); color: var(--accent-purple); }

.card h3 {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.card p {
  color: var(--text-secondary);
  font-size: 0.875rem;
  line-height: 1.6;
  margin-bottom: 20px;
}

.card-link {
  color: var(--accent-green);
  text-decoration: none;
  font-size: 0.875rem;
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: gap 0.15s;
}

.card-link:hover { gap: 8px; }

/* Product cards */
.product-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: 16px;
  padding: 36px;
  transition: all 0.25s;
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  opacity: 0;
  transition: opacity 0.25s;
}

.product-card:hover::before { opacity: 1; }
.product-card:nth-child(1)::before { background: var(--accent-green); }
.product-card:nth-child(2)::before { background: var(--accent-cyan); }
.product-card:nth-child(3)::before { background: var(--accent-purple); }

.product-card:hover {
  border-color: var(--border);
  transform: translateY(-3px);
  box-shadow: 0 8px 32px rgba(0,0,0,0.3);
}

.product-card h3 {
  font-size: 1.375rem;
  font-weight: 700;
  margin-bottom: 12px;
}

.product-card p {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  line-height: 1.7;
  margin-bottom: 24px;
}

/* CLI Section */
.cli-section {
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: 16px;
  padding: 48px;
  overflow: hidden;
}

@media (max-width: 768px) { .cli-section { padding: 24px; } }

.cli-header {
  text-align: center;
  margin-bottom: 40px;
}

.cli-header h2 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
}

.cli-header p {
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto;
  line-height: 1.7;
}

/* Accordion */
.accordion { margin-top: 32px; }

.accordion-item {
  border: 1px solid var(--border-light);
  border-radius: 10px;
  margin-bottom: 8px;
  overflow: hidden;
  background: var(--bg-tertiary);
}

.accordion-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 0.9375rem;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
  transition: background 0.15s;
}

.accordion-trigger:hover { background: rgba(255,255,255,0.03); }

.accordion-trigger .chevron {
  transition: transform 0.2s;
  color: var(--text-muted);
  flex-shrink: 0;
}

.accordion-item.open .accordion-trigger .chevron { transform: rotate(180deg); }

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.accordion-item.open .accordion-content { max-height: 600px; }

.accordion-body {
  padding: 0 20px 20px;
}

.step {
  display: flex;
  gap: 14px;
  margin-bottom: 16px;
}

.step-num {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent-green-dim);
  color: var(--accent-green);
  font-size: 0.75rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 2px;
}

.step-text {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* Tabs */
.tabs {
  display: flex;
  gap: 4px;
  background: var(--bg-primary);
  border-radius: 8px;
  padding: 4px;
  margin-bottom: 12px;
}

.tab-btn {
  padding: 6px 16px;
  border: none;
  background: none;
  color: var(--text-muted);
  font-size: 0.8125rem;
  font-weight: 500;
  font-family: 'JetBrains Mono', monospace;
  cursor: pointer;
  border-radius: 6px;
  transition: all 0.15s;
}

.tab-btn.active {
  background: var(--bg-secondary);
  color: var(--text-primary);
}

.tab-btn:hover:not(.active) { color: var(--text-secondary); }

.code-block {
  background: var(--bg-primary);
  border: 1px solid var(--border-light);
  border-radius: 8px;
  padding: 16px 20px;
  overflow-x: auto;
}

.code-block code {
  font-size: 0.8125rem;
  color: var(--accent-green);
  line-height: 1.7;
}

.code-block .dollar { color: var(--text-muted); }
.code-block .comment { color: var(--text-muted); font-style: italic; }

/* Launch CTA */
.launch-section {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

@media (max-width: 768px) { .launch-section { grid-template-columns: 1fr; } }

.launch-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: 12px;
  padding: 36px;
  transition: all 0.2s;
}

.launch-card:hover { border-color: var(--border); }

.launch-card h3 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 12px;
}

.launch-card p {
  color: var(--text-secondary);
  font-size: 0.875rem;
  line-height: 1.7;
  margin-bottom: 20px;
}

/* Community */
.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

@media (max-width: 768px) { .community-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 480px) { .community-grid { grid-template-columns: 1fr; } }

.community-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: 10px;
  padding: 24px;
  transition: all 0.2s;
  text-decoration: none;
  display: block;
}

.community-card:hover {
  border-color: var(--border);
  transform: translateY(-2px);
}

.community-card h4 {
  font-size: 0.9375rem;
  font-weight: 600;
  margin-bottom: 6px;
}

.community-card p {
  color: var(--text-secondary);
  font-size: 0.8125rem;
  line-height: 1.6;
}

/* Sidebar layout */
.docs-layout {
  display: flex;
  min-height: calc(100vh - 64px);
}

.sidebar {
  width: 260px;
  flex-shrink: 0;
  border-right: 1px solid var(--border-light);
  padding: 24px 0;
  position: sticky;
  top: 64px;
  height: calc(100vh - 64px);
  overflow-y: auto;
  transition: width 0.25s ease, padding 0.25s ease;
}

.sidebar.collapsed {
  width: 0;
  padding: 0;
  overflow: hidden;
}

.sidebar-inner {
  padding: 0 20px;
  min-width: 220px;
}

.sidebar-title {
  font-size: 0.6875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 12px;
}

.sidebar-nav { list-style: none; }

.sidebar-nav li { margin-bottom: 2px; }

.sidebar-nav a {
  display: block;
  padding: 6px 12px;
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 0.8125rem;
  font-weight: 500;
  border-radius: 6px;
  transition: all 0.1s;
}

.sidebar-nav a:hover { background: var(--bg-secondary); color: var(--text-primary); }
.sidebar-nav a.active { background: var(--accent-green-dim); color: var(--accent-green); }

.docs-main {
  flex: 1;
  min-width: 0;
  padding: 40px 48px 80px;
}

@media (max-width: 768px) {
  .docs-layout { flex-direction: column; }
  .sidebar {
    width: 100%;
    height: auto;
    position: relative;
    top: 0;
    border-right: none;
    border-bottom: 1px solid var(--border-light);
  }
  .sidebar.collapsed { height: 0; width: 100%; }
  .docs-main { padding: 24px; }
}

.sidebar-toggle {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: 6px;
  color: var(--text-secondary);
  font-size: 0.8125rem;
  font-weight: 500;
  cursor: pointer;
  margin-bottom: 24px;
  transition: all 0.15s;
  font-family: inherit;
}

.sidebar-toggle:hover { border-color: var(--border); color: var(--text-primary); }

/* Docs content */
.docs-section {
  margin-bottom: 56px;
}

.docs-section h2 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--border-light);
}

.docs-section h3 {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.docs-section p {
  color: var(--text-secondary);
  line-height: 1.7;
  margin-bottom: 16px;
}

.docs-section ul {
  color: var(--text-secondary);
  padding-left: 20px;
  margin-bottom: 16px;
}

.docs-section li { margin-bottom: 8px; line-height: 1.6; }

/* Best practices list */
.practices-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

@media (max-width: 768px) { .practices-grid { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 480px) { .practices-grid { grid-template-columns: 1fr; } }

.practice-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: 8px;
  font-size: 0.875rem;
  font-weight: 500;
}

.practice-icon {
  color: var(--accent-green);
  flex-shrink: 0;
}

/* Protocol diagram */
.protocol-actors {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin: 24px 0;
}

@media (max-width: 768px) { .protocol-actors { grid-template-columns: repeat(2, 1fr); } }

.actor-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: 10px;
  padding: 24px;
  text-align: center;
}

.actor-card .actor-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 12px;
  font-size: 1.5rem;
}

.actor-card h4 { font-size: 1rem; font-weight: 600; margin-bottom: 6px; }
.actor-card p { font-size: 0.8125rem; color: var(--text-secondary); line-height: 1.5; }

/* Badge */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 10px;
  border-radius: 99px;
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.badge-soon {
  background: rgba(184,127,255,0.15);
  color: var(--accent-purple);
}

/* Support categories */
.support-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

@media (max-width: 768px) { .support-grid { grid-template-columns: repeat(2, 1fr; } }
@media (max-width: 480px) { .support-grid { grid-template-columns: 1fr; } }

.support-card {
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: 12px;
  padding: 28px;
  text-align: center;
  transition: all 0.2s;
}

.support-card:hover { border-color: var(--border); transform: translateY(-2px); }

.support-card h4 { font-size: 1rem; font-weight: 600; margin-bottom: 8px; }
.support-card p { font-size: 0.8125rem; color: var(--text-secondary); line-height: 1.5; }

/* Footer */
.footer {
  border-top: 1px solid var(--border-light);
  padding: 48px 0 32px;
  background: var(--bg-primary);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr 1fr;
  gap: 32px;
  margin-bottom: 40px;
}

@media (max-width: 768px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 480px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }
}

.footer-brand p {
  color: var(--text-secondary);
  font-size: 0.8125rem;
  line-height: 1.6;
  margin-top: 12px;
  max-width: 280px;
}

.footer-col h4 {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 16px;
}

.footer-col a {
  display: block;
  color: var(--text-secondary);
  text-decoration: none;
  font-size: 0.8125rem;
  padding: 4px 0;
  transition: color 0.15s;
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  border-top: 1px solid var(--border-light);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.footer-bottom p {
  color: var(--text-muted);
  font-size: 0.75rem;
}

/* Page hero for interior pages */
.page-hero {
  padding: 56px 0 40px;
}

.page-hero h1 {
  font-size: clamp(1.75rem, 4vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
}

.page-hero p {
  color: var(--text-secondary);
  font-size: 1.0625rem;
  max-width: 600px;
  line-height: 1.7;
}

/* Flow steps */
.flow-steps {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.flow-step {
  background: var(--bg-secondary);
  border: 1px solid var(--border-light);
  border-radius: 10px;
  padding: 24px;
  display: flex;
  gap: 16px;
}

.flow-step-num {
  width: 32px;
  height: 32px;
  border-radius: 8px;
  background: var(--accent-green-dim);
  color: var(--accent-green);
  font-weight: 700;
  font-size: 0.875rem;
  display: flex;
  align-items: center;
